import {recordableComponents} from './sequence-properties.js';
import {makeSequenceTrack,validGameplayAsset} from './gameplay-assets.js';
const equal=(a,b,tolerance)=>Array.isArray(a)?a.every((v,i)=>Math.abs(v-b[i])<=tolerance):typeof a==='number'?Math.abs(a-b)<=tolerance:a===b;
export function reduceRecordedKeys(keys,tolerance=1e-4){
 if(!Number.isFinite(tolerance)||tolerance<0)throw Error('키 오차 범위 오류');if(keys.length<3)return structuredClone(keys);
 if(keys.some(k=>k.interpolation==='step'||typeof k.value!=='number'&&!Array.isArray(k.value))){const out=[];for(let i=0;i<keys.length;i++)if(i===0||i===keys.length-1||!equal(keys[i].value,keys[i-1].value,0))out.push(structuredClone(keys[i]));return out;}
 const keep=new Set([0,keys.length-1]),pending=[[0,keys.length-1]];while(pending.length){const [first,last]=pending.pop();if(last-first<=1)continue;let index=-1,error=tolerance;const a=keys[first],b=keys[last];for(let i=first+1;i<last;i++){const alpha=(keys[i].time-a.time)/(b.time-a.time),expected=Array.isArray(a.value)?a.value.map((v,k)=>v+(b.value[k]-v)*alpha):a.value+(b.value-a.value)*alpha,actual=keys[i].value,distance=Array.isArray(actual)?Math.max(...actual.map((v,k)=>Math.abs(v-expected[k]))):Math.abs(actual-expected);if(distance>error){index=i;error=distance;}}if(index>=0){keep.add(index);pending.push([first,index],[index,last]);}}
 return [...keep].sort((a,b)=>a-b).map(i=>structuredClone(keys[i]));
}
export class TakeRecorder {
  constructor({name='Take',fps=30,targets=[],properties=['position','rotation','scale','visible'],capture,includeComponents=true}={}){if(!Number.isInteger(fps)||fps<1||fps>240||!Array.isArray(targets)||!targets.length||!properties.every(p=>['position','rotation','scale','visible'].includes(p)))throw Error('녹화 대상·속성·FPS 오류');Object.assign(this,{name,fps,targets:[...targets],properties,capture,includeComponents,time:0,next:0,tracks:new Map(),frames:0,closed:false});}
  sample(time,objects){if(this.closed)throw Error('녹화가 종료됐어요.');if(!Number.isFinite(time)||time<0||time<this.time)throw Error('녹화 시간 오류');this.time=time;if(time+1e-9<this.next)return;this.next=time+1/this.fps;this.frames++;const owners=new Map(objects.map(o=>[o.id,o]));
   for(const target of this.targets){const object=owners.get(target);if(!object)continue;const rows=this.properties.map(property=>({key:property,type:property,value:object[property],discrete:property==='visible'}));if(this.includeComponents)for(const row of recordableComponents(object))rows.push({...row,key:row.component+'|'+row.property,type:'component'});
    for(const row of rows){const key=target+'|'+row.key;let track=this.tracks.get(key);if(!track){track=makeSequenceTrack(row.type);track.keys=[];track.target=target;track.name=(object.name+' '+row.key).slice(0,80);if(row.type==='component')Object.assign(track,{component:row.component,componentType:row.componentType,property:row.property});this.tracks.set(key,track);}const value=structuredClone(row.value);if(value===undefined)continue;const last=track.keys.at(-1),entry={time,value,interpolation:row.discrete?'step':'linear'};if(!last||last.time<time)track.keys.push(entry);else Object.assign(last,entry);if(track.keys.length>1000000)throw Error('녹화 메모리 예산 초과');}
   }
  }
  finish({tolerance=1e-4}={}){const tracks=[...this.tracks.values()];for(const track of tracks)track.keys=reduceRecordedKeys(track.keys,tolerance);const data={version:1,name:this.name,length:Math.max(.001,this.time),rate:1,fps:this.fps,loop:false,restoreState:true,tracks};if(!validGameplayAsset('sequenceasset',data))throw Error('녹화 결과가 시퀀스 키 예산을 넘었어요. 녹화 시간을 줄이거나 키 오차를 늘리세요.');this.closed=true;return data;}
}
